float hash12(vec2 p)
{
    vec3 p3 = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

float noise(vec2 p)
{
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash12(i);
    float b = hash12(i + vec2(1.0, 0.0));
    float c = hash12(i + vec2(0.0, 1.0));
    float d = hash12(i + vec2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float fbm(vec2 p)
{
    float f = 0.0;
    float a = 0.5;
    for(int i = 0; i < 4; i++)
    {
        f += a * noise(p);
        p *= 2.0;
        a *= 0.5;
    }
    return f;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv = uv * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    vec2 p = uv * 4.0;

    float t = iTime * 0.2;
    p += t * 1.5;

    float f1 = fbm(p + fbm(p + t));
    float f2 = fbm(p * 2.0 + t * 0.5);

    float color = pow(mix(f1, f2, 0.5), 2.0);
    color = max(0.0, color - 0.1);

    vec3 finalColor = vec3(0.0);
    finalColor.r = sin(color * 5.0 + t) * 0.5 + 0.5;
    finalColor.g = sin(color * 5.0 + t + 2.0) * 0.5 + 0.5;
    finalColor.b = sin(color * 5.0 + t + 4.0) * 0.5 + 0.5;

    fragColor = vec4(finalColor, 1.0);
}

