#define PI 3.14159265359

float hash12(vec2 p) {
    vec3 p3  = fract(vec3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

vec2 hash22(vec2 p) {
    p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
    return fract(sin(p) * 43758.5453);
}

mat2 rotate2d(float angle){
    return mat2(cos(angle), -sin(angle), sin(angle), cos(angle));
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);

    vec2 u = f*f*(3.0-2.0*f);

    float a = hash12(i);
    float b = hash12(i + vec2(1.0, 0.0));
    float c = hash12(i + vec2(0.0, 1.0));
    float d = hash12(i + vec2(1.0, 1.0));

    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

float fbm(vec2 p) {
    float f = 0.0;
    f += 0.5000 * noise(p);
    f += 0.2500 * noise(p * 2.0);
    f += 0.1250 * noise(p * 4.0);
    f += 0.0625 * noise(p * 8.0);
    return f / (0.5000 + 0.2500 + 0.1250 + 0.0625);
}

float map(vec3 p) {
    p.xz *= rotate2d(iTime * 0.05);
    float d = 0.0;
    float cloudAmp = 0.6;
    vec3 q = p * 0.1 + vec3(0.0, iTime * 0.02, iTime * 0.03);

    d = fbm(q.xz * 2.0) * cloudAmp; // Base layer of clouds
    d += fbm(q.xy * 0.5) * cloudAmp * 0.5;
    d += fbm(q.yz * 0.7) * cloudAmp * 0.3;

    d = max(0.0, d - p.y); // Clouds are higher up
    d = max(0.0, d - 0.2);
    return d;
}

vec3 calculate_normal(vec3 p) {
    vec2 eps = vec2(0.001, 0.0);
    float d = map(p);
    vec3 n = vec3(
        map(p + eps.xyy) - d,
        map(p + eps.yxy) - d,
        map(p + eps.yyx) - d
    );
    return normalize(n);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    vec3 ro = vec3(sin(iTime * 0.1) * 10.0, 5.0 + sin(iTime * 0.07) * 2.0, cos(iTime * 0.1) * 10.0); // Camera origin
    vec3 target = vec3(0.0, 3.0, 0.0);
    vec3 forward = normalize(target - ro);
    vec3 right = normalize(cross(forward, vec3(0.0, 1.0, 0.0)));
    vec3 up = normalize(cross(right, forward));

    mat3 camMat = mat3(right, up, forward);
    vec3 rd = camMat * normalize(vec3(uv, 1.5)); // Ray direction

    vec3 sunDir = normalize(vec3(0.5, 0.5, -0.5)); // Sun direction
    vec3 skyColor = mix(vec3(0.6, 0.8, 1.0), vec3(0.2, 0.4, 0.6), max(0.0, rd.y)); // Sky gradient

    float t = 0.0;
    float maxDist = 80.0;
    float stepSize = 0.5;
    float densitySum = 0.0;
    vec3 finalColor = skyColor;
    vec3 cloudColor = vec3(1.0, 1.0, 1.0);
    float miePhase = 0.0; // For light scattering
    float g = 0.8; // Anisotropy factor for Mie scattering

    for (int i = 0; i < 60; i++) {
        if (t > maxDist) break; // Early exit if out of bounds

        vec3 p = ro + rd * t;
        float density = max(0.0, map(p));

        if (density > 0.001) {
            float lightRayT = 0.0;
            float lightDensitySum = 0.0;
            for (int j = 0; j < 10; j++) { // Light marching
                vec3 lightP = p + sunDir * lightRayT;
                float lightDensity = max(0.0, map(lightP));
                lightDensitySum += lightDensity;
                lightRayT += 2.0;
            }
            float transmittance = exp(-lightDensitySum * 0.15);

            float scatter = pow(max(0.0, dot(rd, sunDir)) * 0.5 + 0.5, 5.0) * mix(0.5, 1.0, transmittance); // Simple scattering with sun
            miePhase = (1.0 - g*g) / pow(1.0 + g*g - 2.0*g*dot(rd, sunDir), 1.5);
            scatter *= miePhase * 0.1; // Add Mie scattering to intensify sun effect

            float att = exp(-density * stepSize * 4.0); // Attenuation

            finalColor = mix(finalColor, cloudColor * (transmittance * 0.8 + 0.2 + scatter), (1.0 - att) * density);
            densitySum += (1.0 - att) * density;
        }

        t += stepSize;
    }

    finalColor = mix(skyColor, finalColor, 1.0 - exp(-densitySum * 4.0));
    finalColor = mix(finalColor, vec3(1.0, 0.8, 0.6) * 1.5, pow(max(0.0, dot(rd, sunDir)), 10.0)); // Sun disk

    fragColor = vec4(finalColor, 1.0);
}

