    vec2 uv = fragCoord / iResolution.xy;
    vec2 p = uv * 8.0 - vec2(4.0);
    float t = iTime * 0.1;

    // Simple pseudo-random hash function
    vec2 hash2(vec2 x) {
        return fract(sin(vec2(dot(x, vec2(127.1, 311.7)), dot(x, vec2(269.5, 183.3)))) * 43758.5453);
    }

    // 2D Perlin noise function
    float noise(vec2 st) {
        vec2 i = floor(st);
        vec2 f = fract(st);

        vec2 u = f * f * (3.0 - 2.0 * f);

        float a = dot(hash2(i + vec2(0.0, 0.0)), f - vec2(0.0, 0.0));
        float b = dot(hash2(i + vec2(1.0, 0.0)), f - vec2(1.0, 0.0));
        float c = dot(hash2(i + vec2(0.0, 1.0)), f - vec2(0.0, 1.0));
        float d = dot(hash2(i + vec2(1.0, 1.0)), f - vec2(1.0, 1.0));

        return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
    }

    float fbm(vec2 st) {
        float value = 0.0;
        float amplitude = 0.5;
        for (int i = 0; i < 5; i++) {
            value += amplitude * noise(st);
            st *= 2.0;
            amplitude *= 0.5;
        }
        return value;
    }

    vec2 q = vec2(fbm(p + vec2(0.0, t * 1.5)), fbm(p + vec2(5.2, t * 1.2)));
    vec2 r = vec2(fbm(p + q + vec2(1.7, t * 0.8)), fbm(p + q + vec2(8.3, t * 0.7)));
    float f = fbm(p + r + vec2(t * 0.5));

    // Swirling effect
    float swirl_strength = 0.8;
    vec2 swirl_center = vec2(0.0, 0.0);
    vec2 to_center = (p - swirl_center);
    float angle = atan(to_center.y, to_center.x);
    float dist = length(to_center);
    float swirl_amount = sin(dist * 2.0 + t * 0.5) * 0.3;

    vec2 rotated_p = vec2(
        p.x * cos(swirl_amount) - p.y * sin(swirl_amount),
        p.x * sin(swirl_amount) + p.y * cos(swirl_amount)
    );

    f = fbm(rotated_p * 0.8 + r * 0.5 + vec2(t * 0.3));

    // Color palette for stormy Jupiter clouds
    vec3 col_inner = vec3(0.8, 0.6, 0.4); // Light orange/yellow
    vec3 col_middle = vec3(0.6, 0.3, 0.2); // Reddish-brown
    vec3 col_outer = vec3(0.4, 0.2, 0.1); // Dark brown
    vec3 col_storm = vec3(0.9, 0.9, 0.7); // Bright highlight for storm

    vec3 final_color = mix(col_outer, col_middle, smoothstep(0.0, 0.5, f));
    final_color = mix(final_color, col_inner, smoothstep(0.4, 0.8, f));

    // Add some stormy highlights
    float storm_intensity = max(0.0, f - 0.7);
    final_color += col_storm * storm_intensity * 3.0;

    // Add subtle variation with time for evolving atmosphere effect
    final_color += sin(f * 10.0 + t * 2.0) * 0.05;

    fragColor = vec4(final_color, 1.0);
}

