    float tl = random(ip + vec2(0.0, 1.0));
    float tr = random(ip + vec2(1.0, 1.0));
    return mix(mix(bl, br, fp.x), mix(tl, tr, fp.x), fp.y);
}

float fbm(vec2 p) {
    float total = 0.0;
    float amplitude = 1.0;
    float frequency = 0.5;
    for (int i = 0; i < 4; i++) {
        total += noise(p * frequency) * amplitude;
        amplitude *= 0.5;
        frequency *= 2.0;
    }
    return total;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    uv.y *= iResolution.y / iResolution.x; 

    float time = iTime * 0.5;

    vec2 flamePos = vec2(0.5, 0.2);
    float dist = distance(uv, flamePos);

    float flameIntensity = 0.0;
    float flameShape = 1.0 - pow(abs(uv.x - flamePos.x) * 2.0, 2.0);
    flameShape = max(0.0, flameShape - (uv.y - flamePos.y) * 2.0);

