    float mask = -(uv.y - flamePos.y);
    mask = smoothstep(0.0, 0.4, mask);

    flameIntensity *= smoothstep(0.0, 0.3, flameShape);
    flameIntensity *= smoothstep(0.7, 0.0, dist + noise(vec2(time * 0.1, 0.0)) * 0.05);

    vec3 color = vec3(0.0);

    vec3 fireColor1 = vec3(1.0, 0.5, 0.0);
    vec3 fireColor2 = vec3(1.0, 0.1, 0.0);
    vec3 fireColor3 = vec3(1.0, 1.0, 0.0);
    vec3 fireColor4 = vec3(0.8, 0.8, 0.0);

    color = mix(fireColor1, fireColor2, clamp(flameIntensity * 1.5, 0.0, 1.0));
    color = mix(color, fireColor3, clamp(flameIntensity * 2.0 - 0.5, 0.0, 1.0));
    color = mix(color, fireColor4, clamp(flameIntensity * 3.0 - 1.0, 0.0, 1.0));

    color *= flameIntensity * 1.5;

    fragColor = vec4(color * mask, 1.0);
}

