vec2 random2(vec2 st){
    st = vec2( dot(st,vec2(127.1,311.7)),
              dot(st,vec2(269.5,183.3)) );
    return -1.0 + 2.0 * fract(sin(st)*43758.5453123);
}

float voronoi(in vec2 st, in float time) {
    vec2 i = floor(st);
    vec2 f = fract(st);

    float minDist = 1.0;
    for(int y = -1; y <= 1; y++) {
        for(int x = -1; x <= 1; x++) {
            vec2 neighbor = vec2(float(x), float(y));
            vec2 p = i + neighbor;
            vec2 r = random2(p) * 0.5 + 0.5;
            vec2 offset = r + sin(time * 0.5 + dot(r, vec2(1.0, 1.0) * 5.0)) * 0.1; 

            vec2 diff = neighbor + offset - f;
            float dist = length(diff);

            minDist = min(minDist, dist);
        }
    }
    return minDist;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;

    float ar = iResolution.x / iResolution.y;
    uv.x *= ar;

    vec2 st = uv * 5.0 + iTime * 0.1; 

    float v = voronoi(st, iTime);

    vec3 color = vec3(0.0);
    color = mix(vec3(0.0, 0.1, 0.4), vec3(0.8, 0.2, 0.1), smoothstep(0.0, 0.4, v));
    color = mix(color, vec3(0.9, 0.7, 0.1), smoothstep(0.4, 0.8, v));
    color = mix(color, vec3(0.1, 0.6, 0.0), smoothstep(0.8, 1.0, v));

    color *= smoothstep(0.1, 0.0, v);

    fragColor = vec4(color, 1.0);
}

