// SDF for a box
float sdBox(vec3 p, vec3 b) {
    vec3 q = abs(p) - b;
    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

// SDF for a sphere
float sdSphere(vec3 p, float r) {
    return length(p) - r;
}

// SDF for a torus
float sdTorus(vec3 p, vec2 t) {
    vec2 q = vec2(length(p.xz) - t.x, p.y);
    return length(q) - t.y;
}

// SDF for a plane
float sdPlane(vec3 p) {
    return p.y + 0.5;
}

// Scene SDF with material IDs
vec2 map(vec3 p) {
    float orbitRadius = 1.5; // Radius of orbit
    float orbitSpeed = 2.0;  // Speed of orbit

    vec3 center = vec3(0.0, 0.5, 0.0); // Center of orbit

    // Sphere 1
    vec3 p1 = center + vec3(orbitRadius * cos(iTime * orbitSpeed), 0.0, orbitRadius * sin(iTime * orbitSpeed));
    float sphere1 = sdSphere(p - p1, 1.0);

    // Sphere 2 (opposite side)
    vec3 p2 = center + vec3(orbitRadius * cos(iTime * orbitSpeed + 3.14159), 0.0, orbitRadius * sin(iTime * orbitSpeed + 3.14159));
    float sphere2 = sdSphere(p - p2, 1.0);

    // Ground plane
    float plane = sdPlane(p);

    // Return closest object with material ID
    vec2 res = vec2(sphere1, 1.0); // Red sphere
    if (sphere2 < res.x) res = vec2(sphere2, 2.0); // Blue sphere
    if (plane < res.x) res = vec2(plane, 3.0); // Gray plane

    return res;
}

// Calculate normal using gradient
vec3 calcNormal(vec3 p) {
    vec2 e = vec2(0.001, 0.0);
    return normalize(vec3(
        map(p + e.xyy).x - map(p - e.xyy).x,
        map(p + e.yxy).x - map(p - e.yxy).x,
        map(p + e.yyx).x - map(p - e.yyx).x
    ));
}

// Soft shadow calculation
float calcShadow(vec3 ro, vec3 rd, float mint, float maxt, float k) {
    float shadow = 1.0;
    float t = mint;

    for (int i = 0; i < 50; i++) {
        float h = map(ro + rd * t).x;

        if (h < 0.001) {
            return 0.0;
        }

        shadow = min(shadow, k * h / t);

        t += h;

        if (t > maxt) break;
    }

    return clamp(shadow, 0.0, 1.0);
}

// Ray marching function
vec2 rayMarch(vec3 ro, vec3 rd) {
    float t = 0.0;
    float matID = -1.0;

    for (int i = 0; i < 100; i++) {
        vec3 p = ro + rd * t;
        vec2 h = map(p);

        if (h.x < 0.001) {
            matID = h.y;
            break;
        }

        t += h.x;

        if (t > 100.0) break;
    }

    return vec2(t, matID);
}

// Get material color based on ID
vec3 getMaterialColor(float matID) {
    if (matID == 1.0) return vec3(1.0, 0.1, 0.1);
    if (matID == 2.0) return vec3(0.1, 0.3, 1.0);
    if (matID == 3.0) return vec3(0.6, 0.6, 0.6);
    return vec3(0.5, 0.7, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    vec3 ro = vec3(0.0, 3.0, 8.0);
    vec3 target = vec3(0.0, 0.5, 0.0);

    vec3 forward = normalize(target - ro);
    vec3 right = normalize(cross(vec3(0.0, 1.0, 0.0), forward));
    vec3 up = cross(forward, right);

    vec3 rd = normalize(forward + uv.x * right + uv.y * up);

    vec2 res = rayMarch(ro, rd);
    float t = res.x;
    float matID = res.y;

    vec3 col;

    if (matID > 0.0) {
        vec3 p = ro + rd * t;
        vec3 normal = calcNormal(p);

        vec3 lightDir = normalize(vec3(0.5, 0.8, 0.3));
        float diff = max(dot(normal, lightDir), 0.0);

        float shadow = 1.0;
        if (diff > 0.0) {
            shadow = calcShadow(p + normal * 0.01, lightDir, 0.02, 10.0, 8.0);
        }

        float ambient = 0.3;

        vec3 matCol = getMaterialColor(matID);

